function mockBodyFor(url, method, rawBody) {
    if (/featurevisor-tag-/.test(url) && method === "GET")
        return LOCAL_PREVIEW_FEATURES;
    if (/local-preview\.invalid\/upload/.test(url) && method === "PUT")
        return {};
    if (method === "POST" && /\/documents\/upload\/bulk(?:\?|$)/.test(url)) {
        const parsed = readJson(rawBody);
        const files = Array.isArray(parsed.files) ? parsed.files : [];
        const file = (files[0] ?? {});
        return {
            files: [
                {
                    documentId: "doc-sample-zip",
                    name: file.name ?? "sample-documents.zip",
                    uploadUrl: "https://local-preview.invalid/upload/doc-sample-zip",
                    headers: {},
                    processingSteps: [],
                },
            ],
        };
    }
    if (method === "POST" && /\/mortgage-applications(?:\?|$)/.test(url)) {
        return rememberCreatedCase(rawBody);
    }
    if (method === "POST" && /\/bank-applications\/[^/?]+\/zip-packages(?:\?|$)/.test(url)) {
        return { zipId: "zip-demo" };
    }
    if (method === "POST" && /\/documents\/[^/?]+\/download(?:\?|$)/.test(url)) {
        return { downloadUrl: DEMO_ZIP_DOWNLOAD_URL };
    }
    const extractedPatch = url.match(/\/documents\/([^/?]+)\/extracted-fields(?:\?|$)/);
    if (method === "PATCH" && extractedPatch) {
        const parsed = readJson(rawBody);
        const fields = Array.isArray(parsed.fields) ? parsed.fields : [];
        return localPreviewPatchedExtractedFields(fields);
    }
    if (method !== "GET")
        return undefined;
    if (/\/api\/v1\/users\/me(?:\?|$)/.test(url))
        return LOCAL_PREVIEW_USER_API;
    if (/credit-ops\/bank-applications(?:\?|$)/.test(url))
        return previewList();
    const validation = url.match(/\/bank-applications\/([^/?]+)\/document-validation-checks(?:\?|$)/);
    if (validation)
        return localPreviewValidationChecks(validation[1]);
    if (/\/bank-applications\/[^/?]+\/bank-policy-checks(?:\?|$)/.test(url)) {
        return localPreviewPolicyChecks();
    }
    const eligibility = url.match(/\/bank-applications\/([^/?]+)\/eligibility-checks(?:\?|$)/);
    if (eligibility) {
        const row = findPreviewRow(eligibility[1]);
        return localPreviewEligibility(eligibility[1], row?.mortgageApplication.applicantFullName ?? "Marc Aoun");
    }
    if (/\/zips\/[^/?]+(?:\?|$)/.test(url)) {
        return {
            id: "zip-demo",
            generatedDocumentId: "doc-generated-zip",
            documentIdsToZip: ["doc-sample-zip"],
            status: "COMPLETED",
        };
    }
    if (/\/earning-types(?:\?|$)/.test(url))
        return LOCAL_PREVIEW_EARNING_TYPES;
    if (/\/liability-types(?:\?|$)/.test(url))
        return LOCAL_PREVIEW_LIABILITY_TYPES;
    const extracted = url.match(/\/documents\/([^/?]+)\/extracted-fields(?:\?|$)/);
    if (extracted)
        return localPreviewExtractedFields(decodeURIComponent(extracted[1]));
    const document = url.match(/\/documents\/([^/?]+)(?:\?|$)/);
    if (document) {
        return {
            documentId: document[1],
            name: "sample-documents.zip",
            contentType: "application/zip",
            sizeInBytes: 1024,
            createdAt: PREVIEW_CALCULATED_AT,
            isUploaded: true,
            uploadedAt: PREVIEW_CALCULATED_AT,
            metadata: {},
            isPublic: false,
            previewUrl: "",
            downloadUrl: DEMO_ZIP_DOWNLOAD_URL,
            variations: [],
        };
    }
    const detail = url.match(/\/api\/v1\/bank-applications\/([^/?]+)(?:\?|$)/);
    if (detail)
        return localPreviewBankApplicationDetail(detail[1], findPreviewRow(detail[1]));
    if (/\/document-type-codes(?:\?|$)/.test(url))
        return LOCAL_PREVIEW_DOCUMENT_TYPE_CODES;
    const opportunity = url.match(/\/opportunities\/([^/?]+)(?:\?|$)/);
    if (opportunity)
        return localPreviewOpportunity(decodeURIComponent(opportunity[1]));
    if (/\/api\/v1\/banks(?:\?|$)/.test(url))
        return LOCAL_PREVIEW_BANKS;
    return undefined;
}
